  '<div class="btn-row"><button class="btn primary" id="ts-apply" type="button">Сохранить и начать новую игру</button><button class="btn" id="ts-save" type="button">Только сохранить</button></div>': '<div class="btn-row"><button class="btn primary" id="ts-apply" type="button">Save and start a new game</button><button class="btn" id="ts-save" type="button">Save only</button></div>',
